// Replace with your N2YO API key from https://www.n2yo.com/api/
const API_KEY = 'YOUR_N2YO_API_KEY';

// Observer location — replace with your coordinates and altitude in metres
const OBS_LAT = 0.0000;   // e.g. -35.2809
const OBS_LON = 0.0000;   // e.g. 149.1287
const OBS_ALT = 0;        // metres ASL, e.g. 600

// Add your N2YO-tracked satellites here (must have NORAD IDs resolvable by N2YO)
// Format: { name: 'DISPLAY_NAME', catnr: NORAD_ID }
const targets = [
    // { name: 'ISS', catnr: 25544 },
    // { name: 'EXAMPLE-SAT', catnr: 99999 }
];

targets.forEach(t => {
    node.send({
        satName: t.name,
        url: `https://api.n2yo.com/rest/v1/satellite/positions/${t.catnr}/${OBS_LAT}/${OBS_LON}/${OBS_ALT}/1/&apiKey=${API_KEY}`
    });
});
return null;

const url = msg.url;
const satName = msg.satName;

return new Promise((resolve) => {
    const req = https.get(url, {
        headers: { 'User-Agent': 'NodeRED-SatTracker/1.0', 'Accept': 'application/json' },
        timeout: 10000
    }, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
            msg.statusCode = res.statusCode;
            try { msg.payload = JSON.parse(data); delete msg.error; }
            catch(e) { msg.error = { message: 'JSON parse failed' }; }
            resolve(msg);
        });
    });
    req.on('error', err => { msg.error = { message: err.message }; resolve(msg); });
    req.on('timeout', () => { req.destroy(); msg.error = { message: 'timeout' }; resolve(msg); });
}).then(m => m);

if (msg.error) {
    node.status({fill:'red', shape:'ring', text: msg.satName + ': ' + msg.error.message});
    return null;
}
if (msg.statusCode !== 200) {
    node.status({fill:'red', shape:'ring', text: msg.satName + ': HTTP ' + msg.statusCode});
    return null;
}
const body = msg.payload;
if (!body || !body.positions || !body.positions[0]) {
    node.status({fill:'yellow', shape:'ring', text: msg.satName + ': no pos'});
    return null;
}
const pos = body.positions[0];
msg.payload = {
    name: msg.satName,
    lat:  pos.satlatitude,
    lon:  pos.satlongitude,
    alt:  pos.sataltitude
};
node.status({fill:'green', shape:'dot', text: msg.satName + ' ' + pos.satlatitude.toFixed(1) + ',' + pos.satlongitude.toFixed(1)});
return msg;

// Add all satellites you want tracked via SatNOGS TLE (SGP4 propagation)
// These can include satellites not available via N2YO
// Format: { name: 'DISPLAY_NAME', catnr: NORAD_ID }
// SatNOGS uses NORAD IDs; newly launched satellites may appear here before N2YO
const targets = [
    // { name: 'ISS',       catnr: 25544 },
    // { name: 'EXAMPLE-A', catnr: 98391 },
    // { name: 'EXAMPLE-B', catnr: 98392 }
];

targets.forEach(t => {
    node.send({
        satName: t.name,
        url: `https://db.satnogs.org/api/tle/?norad_cat_id=${t.catnr}&format=json`
    });
});
return null;

const url = msg.url;
const satName = msg.satName;

return new Promise((resolve) => {
    const req = https.get(url, {
        headers: { 'User-Agent': 'NodeRED-SatTracker/1.0', 'Accept': 'application/json' },
        timeout: 10000
    }, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
            msg.statusCode = res.statusCode;
            try { msg.payload = JSON.parse(data); delete msg.error; }
            catch(e) { msg.error = { message: 'JSON parse failed' }; }
            resolve(msg);
        });
    });
    req.on('error', err => { msg.error = { message: err.message }; resolve(msg); });
    req.on('timeout', () => { req.destroy(); msg.error = { message: 'timeout' }; resolve(msg); });
}).then(m => m);

if (msg.error) {
    node.status({fill:'red', shape:'ring', text: msg.satName + ': ' + msg.error.message});
    return null;
}
if (msg.statusCode !== 200) {
    node.status({fill:'red', shape:'ring', text: msg.satName + ': HTTP ' + msg.statusCode});
    return null;
}
const results = msg.payload;
if (!Array.isArray(results) || results.length === 0) {
    node.status({fill:'yellow', shape:'ring', text: msg.satName + ': not in catalog'});
    return null;
}
const entry = results[0];
const tle1 = String(entry.tle1 || '').trim();
const tle2 = String(entry.tle2 || '').trim();

if (tle1.length < 60 || tle2.length < 60) {
    node.status({fill:'red', shape:'ring', text: msg.satName + ': bad TLE'});
    return null;
}

const cache = global.get('tleCache') || {};
cache[msg.satName] = { tle1, tle2, updated: Date.now() };
global.set('tleCache', cache);

node.status({fill:'green', shape:'dot', text: msg.satName + ' cached | keys: ' + Object.keys(cache).join(', ')});
return null;

const cache = global.get('tleCache') || {};
const names = Object.keys(cache);

if (names.length === 0) {
    node.status({fill:'yellow', shape:'ring', text:'No TLEs cached yet'});
    return null;
}

names.forEach(name => {
    const entry = cache[name];
    node.send({
        payload: { name, tle1: entry.tle1, tle2: entry.tle2 }
    });
});

node.status({fill:'green', shape:'dot', text: names.join(', ') + ' fanned out'});
return null;

const name = String(msg.payload.name).trim();
const tle1 = msg.payload.tle1;
const tle2 = msg.payload.tle2;

let satrec;
try { satrec = satellite.twoline2satrec(tle1, tle2); }
catch(e) { node.status({fill:'red', shape:'ring', text: name + ': TLE parse fail'}); return null; }

const now    = new Date();
const posVel = satellite.propagate(satrec, now);

if (!posVel.position || posVel.position === false) {
    node.status({fill:'red', shape:'ring', text: name + ': propagation fail'});
    return null;
}

const gmst = satellite.gstime(now);
const geo  = satellite.eciToGeodetic(posVel.position, gmst);

msg.payload = {
    name,
    lat: satellite.degreesLat(geo.latitude),
    lon: satellite.degreesLong(geo.longitude),
    alt: geo.height
};

node.status({fill:'green', shape:'dot', text: name + ' ' + msg.payload.lat.toFixed(1) + ',' + msg.payload.lon.toFixed(1)});
return msg;

const sat = msg.payload;
const name = String(sat.name).trim();
const lat  = sat.lat;
const lon  = sat.lon;
const altKm = sat.alt;

if (typeof lat !== 'number' || typeof lon !== 'number') {
    node.status({fill:'red', shape:'ring', text: name + ': invalid pos'});
    return null;
}

const safeName = name.replace(/[^a-zA-Z0-9_\-]/g, '_');
const satUid   = 'SAT-' + safeName;
const footUid  = 'SAT-' + safeName + '-footprint';
const trackUid = 'SAT-' + safeName + '-track';

const now   = new Date();
const stale = new Date(now.getTime() + 90000);
const isoZ  = d => d.toISOString();

const aprsRemark = 'APRS: 145.825MHz Path: ARISS | alt ' + altKm.toFixed(0) + ' km';

const R_EARTH_KM = 6371;
const footRadiusKm = Math.sqrt(Math.pow(R_EARTH_KM + altKm, 2) - Math.pow(R_EARTH_KM, 2));

function normLon(l) {
    while (l >  180) l -= 360;
    while (l < -180) l += 360;
    return l;
}

function splitAtAntimeridian(points) {
    if (points.length === 0) return [];
    const segments = [];
    let current = [points[0]];
    for (let i = 1; i < points.length; i++) {
        const prev = current[current.length - 1].lon;
        const curr = normLon(points[i].lon);
        const diff = curr - prev;
        if (Math.abs(diff) > 180) {
            segments.push(current);
            current = [{ lat: points[i].lat, lon: curr }];
        } else {
            current.push({ lat: points[i].lat, lon: curr });
        }
    }
    segments.push(current);
    return segments;
}

const NUM_VERTICES = 64;
const latRad = lat * Math.PI / 180;
const lonRad = lon * Math.PI / 180;

const rawAngDist = footRadiusKm / R_EARTH_KM;
const maxAngDist = (Math.PI / 2) - Math.abs(latRad) - 0.01;
const angDist = Math.min(rawAngDist, maxAngDist);

const rawFootVertices = [];
for (let i = 0; i <= NUM_VERTICES; i++) {
    const bearing = (i % NUM_VERTICES / NUM_VERTICES) * 2 * Math.PI;
    const vLatRad = Math.asin(
        Math.sin(latRad) * Math.cos(angDist) +
        Math.cos(latRad) * Math.sin(angDist) * Math.cos(bearing)
    );
    let vLonRad = lonRad + Math.atan2(
        Math.sin(bearing) * Math.sin(angDist) * Math.cos(latRad),
        Math.cos(angDist) - Math.sin(latRad) * Math.sin(vLatRad)
    );
    rawFootVertices.push({
        lat: vLatRad * 180 / Math.PI,
        lon: normLon(vLonRad * 180 / Math.PI)
    });
}

const footSegments = splitAtAntimeridian(rawFootVertices);

const rawTrackPoints = [];
const cache    = global.get('tleCache') || {};
const tleEntry = cache[name];

if (tleEntry) {
    let satrec;
    try { satrec = satellite.twoline2satrec(tleEntry.tle1, tleEntry.tle2); } catch(e) { satrec = null; }
    if (satrec) {
        for (let m = 1; m <= 60; m++) {
            const futureTime = new Date(now.getTime() + m * 60000);
            const pv = satellite.propagate(satrec, futureTime);
            if (!pv.position || pv.position === false) continue;
            const gmst = satellite.gstime(futureTime);
            const geo  = satellite.eciToGeodetic(pv.position, gmst);
            rawTrackPoints.push({
                lat: satellite.degreesLat(geo.latitude),
                lon: normLon(satellite.degreesLong(geo.longitude))
            });
        }
    }
}

const trackSegments = splitAtAntimeridian(rawTrackPoints);

const strokeCyan = -16711681;
const fillCyan   =  872349951;
const strokeRed  = -65536;

const cotType = 'a-f-P-S';

node.send({ payload: {
    event: {
        $: { version:'2.0', uid:satUid, type:cotType, time:isoZ(now), start:isoZ(now), stale:isoZ(stale), how:'m-g' },
        point: { $: { lat:lat.toFixed(6), lon:lon.toFixed(6), hae:(altKm*1000).toFixed(0), ce:'9999999', le:'9999999' } },
        detail: {
            contact: { $: { callsign: name } },
            remarks: { _: aprsRemark }
        }
    }
}});

footSegments.forEach((seg, idx) => {
    if (seg.length < 2) return;
    node.send({ payload: {
        event: {
            $: { version:'2.0', uid:footUid + (footSegments.length > 1 ? '-' + idx : ''), type:'u-d-f', time:isoZ(now), start:isoZ(now), stale:isoZ(stale), how:'h-e' },
            point: { $: { lat:lat.toFixed(6), lon:lon.toFixed(6), hae:'0', ce:'9999999', le:'9999999' } },
            detail: {
                contact:      { $: { callsign: name + ' footprint' } },
                strokeColor:  { $: { value: strokeCyan.toString() } },
                strokeWeight: { $: { value: '2' } },
                fillColor:    { $: { value: idx === 0 ? fillCyan.toString() : '0' } },
                labels_on:    { $: { value: 'false' } },
                link: seg.map(v => ({ $: { point: v.lat.toFixed(6)+','+v.lon.toFixed(6), type:'b-x-KmlGeofence' } })),
                remarks: { _: name + ' coverage footprint ' + footRadiusKm.toFixed(0) + ' km radius' }
            }
        }
    }});
});

trackSegments.forEach((seg, idx) => {
    if (seg.length < 2) return;
    node.send({ payload: {
        event: {
            $: { version:'2.0', uid:trackUid + '-' + idx, type:'u-d-f', time:isoZ(now), start:isoZ(now), stale:isoZ(stale), how:'h-e' },
            point: { $: { lat:seg[0].lat.toFixed(6), lon:seg[0].lon.toFixed(6), hae:'0', ce:'9999999', le:'9999999' } },
            detail: {
                contact:      { $: { callsign: name + ' track' } },
                strokeColor:  { $: { value: strokeRed.toString() } },
                strokeWeight: { $: { value: '2' } },
                fillColor:    { $: { value: '0' } },
                labels_on:    { $: { value: 'false' } },
                closed:       { $: { value: 'false' } },
                link: seg.map(v => ({ $: { point: v.lat.toFixed(6)+','+v.lon.toFixed(6), type:'b-x-KmlGeofence' } })),
                remarks: { _: name + ' 60 min ground track' }
            }
        }
    }});
});

node.status({fill:'green', shape:'dot', text: name + ' foot:' + footSegments.length + ' track:' + trackSegments.length + ' segs'});
return null;

let xml = msg.payload;
if (typeof xml !== 'string') xml = String(xml);
msg.payload = xml + '\n';
node.status({fill:'green', shape:'dot', text: 'Sent ' + xml.length + ' bytes'});
return msg;
